mapper.select:
SELECT s.row_number AS "rowNumber", s.row_payload::text AS "payload"
FROM excel_upload_staging_rows s WHERE s.upload_id = #{uploadId}
ORDER BY s.row_number FOR UPDATE

SELECT u.user_id FROM users u
WHERE u.employee_no = #{employeeNo}
  AND u.status = 'ACTIVE' AND u.system_use_yn = 'Y'

SELECT COUNT(*) FROM evaluation_element_management_item_settings item
WHERE item.management_item_code = #{code}
  AND item.area_code = 'EDUCATION' AND item.active_yn = 'Y'

SELECT COUNT(*) FROM education_achievements a
WHERE a.achievement_type = 'EMPLOYMENT_RATE_ACHIEVEMENT'
  AND a.deleted_yn = 'N'
  AND a.teacher_user_id = #{teacherId}
  AND a.evaluation_year = #{year}
  AND a.management_item_code = #{code}
  AND a.achievement_date = CAST(#{date} AS date)
  AND COALESCE(a.achievement_name, '') = #{name}
